CREATE TABLE IF NOT EXISTS `websocket_config` (
    `id` varchar(200) NOT NULL COMMENT '主键ID，无业务含义',
    `function_type` varchar(200) DEFAULT NULL COMMENT '功能编码',
    `class_code` varchar(200) DEFAULT NULL COMMENT '对象类编码',
    `class_name` varchar(200) DEFAULT NULL COMMENT '对象类名称',
    `info_code` varchar(200) DEFAULT NULL COMMENT '信息点编码',
    `info_name` varchar(200) DEFAULT NULL COMMENT '信息点名称',
    `first_tag` varchar(200) DEFAULT NULL COMMENT '一级标签',
    `second_tag` varchar(200) DEFAULT NULL COMMENT '二级标签',
    PRIMARY KEY (`id`) USING BTREE,
    KEY `nk_websocket_function_type` (`function_type`) USING BTREE COMMENT '功能编码',
    KEY `nk_websocket_class_code` (`class_code`) USING BTREE COMMENT '设备类级别索引'
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 ROW_FORMAT = DYNAMIC COMMENT = 'WEBSOCKET 推送数据配置详情';

DELETE FROM websocket_config;
